from logging import getLogger
from datetime import datetime
from threading import Thread
from time import sleep
from collections import defaultdict

from requests.exceptions import ConnectionError, ConnectTimeout, ReadTimeout

from ute_common_admin.exception import AdminApiConnectionClosedException, AdminApiTerminatedException, \
    AdminApiNoResponseException, AdminApiProcedureTimeoutException, AdminApiProcedureFailureException

from .bts_factory import BtsFactory
from .status_factory import StatusFactory
from .exceptions import BtsConnectionError, WatchdogAlreadyStarted, WatchdogNotStarted, ComponentCheckError, \
    UnexpectedStatusesDetected
from .reporter import Reporter


class Watchdog(object):
    def __init__(self, bts_config, interval=2.0):
        """
        :param bts_config: configuration object of BTS to which requests for current statuses will be send;
                           should contain all data required to connect to given BTS;
                           if None will be provided then ClassicalBts with default connection details will be used
        :type bts_config: taf.config.testline.gnb.gnb.gNB or None
        :param interval: time interval between consecutive requests to BTS for current statuses;
                         defaults to 2 sec
        :type interval: float or int
        :raises InvalidBtsType: when requested BTS type from BTS config is unsupported
        """
        self._bts = BtsFactory.get_bts(bts_config=bts_config, alias='status_watchdog_{}'.format(id(self)))
        self._interval = interval
        self._keep_watching = False
        self._watcher = None
        self._expected_statuses = []
        self._stop_conditions = defaultdict(list)
        self._current_statuses = []
        self._detected_statuses = []
        self._history_of_statuses = []
        self._logger = getLogger()
        self._log_info_msg("New watchdog created")

    def watch_statuses(self, log_dir=''):
        """
        Starts watching current statuses on BTS to detect any occurrence of unexpected status.

        Doesn't block test execution, status watching is done in parallel with main thread.
        Must always be used together with stop_watching_statuses keyword, preferably put in test's teardown.
        After starting status watch it will wait one interval for potential unexpected statuses to be read from BTS.
        If current statuses cannot be read from BTS (due to its unavailability) then status watch doesn't get stopped.

        BTS is asked for current statuses every time when time interval passes.
        Unexpected statuses are those which were not expected either via expect_status nor expect_statuses keywords.
        If unexpected status is detected then it is saved in watch history.
        If unexpected status stops being read from BTS then it is marked as lost in watch history.
        Detected unexpected status history can be checked with check_unexpected_statuses keyword.

        :param log_dir: path to directory where additional logs will be stored;
                        defaults to '' (logs will be stored in current working directory)
        :type log_dir: str
        :raises WatchdogAlreadyStarted: when re-starting statuses watch was not preceded with stopping statuses watch
        :raises BtsConnectionError: when connection to BTS cannot be established
        """
        self._log_info_msg("Starting watchdog")
        self._check_for_already_started_watch()
        self._connect_to_bts(log_dir)
        self._start_watcher()
        self._log_info_msg("Watchdog started")

    def add_expected_status(self, component, name, value, check_component=False):
        """
        Adds status to list of expected statuses.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        If (at any point in time) this expected status will not be read from BTS,
        then such event will be recorded in watch history.
        Can be used to dynamically change expected statuses during test case execution.

        :param component: runtime distName of component for which given status should be expected
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of expected status, i.e. 'availabilityStatus'
        :type name: str
        :param value: value of expected status, i.e. 'Offline';
                      use None when expecting status without value (i.e. 'Online' after CNI-61110)
        :type value: str or None
        :param check_component: flag indicating whether component existence should be checked before adding
                                expected status; defaults to False
        :type check_component: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises InvalidStatus: when expected status has invalid data
        :raises ComponentCheckError: when BTS was unavailable during component check or
                                     given component doesn't exist on BTS
        """
        self._log_info_msg("Adding expected status with component: {}, name: {} and value: {}".format(
            component, name, value))
        self._check_for_not_started_watch(self.add_expected_status.__name__)
        expected_status = StatusFactory.create_expected_status(component=component, name=name, value=value)
        if check_component:
            self._check_if_component_exists_on_bts(component)
        self._try_update_expected_status(expected_status)
        self._try_add_new_expected_status(expected_status)
        self._log_info_msg("Expected status added")

    def add_expected_statuses(self, component, names_and_values, check_component=False):
        """
        Adds multiple statuses to list of expected statuses.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        If (at any point in time) these expected statuses will not be read from BTS,
        then such event will be recorded in watch history.
        Can be used to dynamically change expected statuses during test case execution.

        :param component: runtime distName of component for which given statuses should be expected
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param names_and_values: data of statuses which should be expected;
                                    should be in form of dictionary {name: value};
                                    use None for value when expecting status without value (i.e. 'Online' after CNI-61110)
                                    i.e. {'availabilityStatus': 'Offline', 'operationalState': 'Disabled'}
        :type names_and_values: {str: str or None}
        :param check_component: flag indicating whether component existence should be checked before adding
                                expected statuses; defaults to False
        :type check_component: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises InvalidStatus: when any expected status has invalid data
        :raises ComponentCheckError: when BTS was unavailable during component check or
                                     given component doesn't exist on BTS
        :return: list of expected statuses added to watch for given component
        :rtype: [ExpectedStatus]
        """
        self._log_info_msg("Adding expected statuses with component: {} and statuses: {}".format(
            component, names_and_values)
        )
        self._check_for_not_started_watch(self.add_expected_statuses.__name__)
        if check_component:
            self._check_if_component_exists_on_bts(component)

        expected_statuses = []
        for name, value in names_and_values.items():
            expected_status = StatusFactory.create_expected_status(component=component, name=name, value=value)
            self._try_update_expected_status(expected_status)
            self._try_add_new_expected_status(expected_status)
            expected_statuses.append(expected_status)
        self._log_info_msg("Expected statuses added")

        return expected_statuses

    def add_stop_conditions(self, component, names_and_values, watched_statuses):
        """
        Adds stop condition for given statuses.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        If given statuses will have different values than expected statuses then given statuses will be removed from
        expected statuses list.
        Can be used to dynamically change expected statuses during test case execution.

        :param component: runtime distName of component for which given statuses should be checked
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param names_and_values: data of statuses which should be checked;
                                    should be in form of dictionary {name: value};
                                    use None for value when expecting status without value
                                    (i.e. 'Online' after CNI-61110)
                                    i.e. {'availabilityStatus': 'Offline', 'operationalState': 'Disabled'}
        :type names_and_values: {str: str or None}
        :param watched_statuses: list of statuses which should be removed from expected statuses list when
                                 stop condition is met
        :type watched_statuses: [ExpectedStatus]
        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises InvalidStatus: when any status from stop condition has invalid data
        :raises ComponentCheckError: when BTS was unavailable during component check or
                                     given component doesn't exist on BTS
        """
        self._log_info_msg("Adding stop condition with component: {}, statuses: {} for watched statuses: {}".format(
            component, names_and_values, watched_statuses)
        )
        self._check_for_not_started_watch(self.add_stop_conditions.__name__)

        for name, value in names_and_values.items():
            stop_condition = StatusFactory.create_expected_status(component=component, name=name, value=value)
            self._add_new_stop_condition(stop_condition, watched_statuses)
        self._log_info_msg(f"Stop condition statuses for {component} added")

    def check_unexpected_statuses(self):
        """
        Checks whether watch history contains any unexpected statuses.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        Status watching will be continued despite any unexpected statuses being detected or not.

        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises UnexpectedStatusesDetected: when watch history contains any unexpected status
        :raises InvalidStatus: when any status from history has invalid data
        """
        self._log_info_msg("Checking unexpected statuses")
        self._check_for_not_started_watch(self.check_unexpected_statuses.__name__)

        if self._history_of_statuses:
            report = Reporter.generate_report_from_status_history(status_history=self._history_of_statuses)
            raise UnexpectedStatusesDetected("\n{}".format(report))

        self._log_info_msg("No unexpected statuses detected")

    def stop_watching_statuses(self):
        """
        Stops watching current statuses on BTS.

        Required to use every time when watch_statuses keyword is used.
        Stops status watching sub-thread which was run in background, disconnects from BTS and resets watchdog state,
        so it is recommended to use it in test's teardown.
        It is allowed to use this keyword even if statuses watching was already stopped before (or not started at all).
        """
        self._log_info_msg("Stopping status watch")
        self._stop_watcher()
        self._disconnect_from_bts()
        self._reset()
        self._log_info_msg("Status watch stopped")

    def _check_for_already_started_watch(self):
        if self._keep_watching:
            raise WatchdogAlreadyStarted(
                "Before re-starting statuses watch it must be stopped first - use stop_watching_statuses")

    def _connect_to_bts(self, log_dir):
        try:
            self._bts.connect_to(log_dir=log_dir)
        except (AdminApiConnectionClosedException,
                AdminApiTerminatedException,
                ConnectionError) as api_error:
            raise BtsConnectionError("Status Watchdog cannot connect to BTS due to following API error: {}".format(
                api_error))

    def _start_watcher(self):
        self._log_debug_msg("Starting watcher with {}s interval".format(self._interval))
        self._keep_watching = True
        self._watcher = Thread(target=self._watch)
        self._watcher.start()
        self._wait()
        self._log_debug_msg("Watcher started")

    def _watch(self):
        while self._should_still_watch():
            if self._are_there_expected_statuses():
                start_time = datetime.now()
                self._get_current_statuses()
                self._check_for_detected_statuses()
                self._check_for_lost_statuses()
                self._check_stop_conditions_for_watched_components()
                self._wait(elapsed_time=self._get_time_delta(start_time, datetime.now()))

    def _should_still_watch(self):
        return self._keep_watching

    def _are_there_expected_statuses(self):
        return bool(self._expected_statuses)

    def _get_current_statuses(self):
        statuses_to_watch = self._get_statuses_to_watch()
        current_statuses = []

        for component, expected_component_statuses in statuses_to_watch.items():
            read_component_statuses = self._read_component_statuses(component)

            if read_component_statuses:
                current_component_statuses = self._create_current_statuses(expected_component_statuses,
                                                                           read_component_statuses)
                current_statuses.extend(current_component_statuses)

        self._current_statuses = current_statuses

    def _get_statuses_to_watch(self):
        statuses_to_watch = {}

        for expected_status in self._expected_statuses:
            if expected_status.component not in statuses_to_watch:
                statuses_to_watch[expected_status.component] = [expected_status]
            else:
                statuses_to_watch[expected_status.component].append(expected_status)

        return statuses_to_watch

    def _check_stop_conditions_for_watched_components(self):
        component_statuses_cache = {}
        for watched_status, stop_conditions in self._stop_conditions.items():
            current_condition_statuses = {}
            for stop_condition in stop_conditions:
                if stop_condition.component not in component_statuses_cache:
                    component_statuses_cache[stop_condition.component] = self._read_component_statuses(
                        stop_condition.component
                    )

                current_component_status = self._create_current_status(
                    stop_condition,
                    component_statuses_cache[stop_condition.component]
                )
                current_condition_statuses[stop_condition] = current_component_status

            if current_condition_statuses and self._check_stop_condition(current_condition_statuses):
                self._log_debug_msg(f"Stop condition met for watched status: {watched_status}")
                self._expected_statuses.remove(watched_status)
                self._log_info_msg(f"{watched_status} removed from expected statuses")

    @staticmethod
    def _check_stop_condition(current_condition_statuses):
        return all(stop_condition == current_component_status
                   for stop_condition, current_component_status in current_condition_statuses.items())

    def _read_component_statuses(self, component):
        try:
            return self._bts.get_statuses(dist_name=component, timeout=self._interval)
        except (AdminApiNoResponseException,
                AdminApiProcedureTimeoutException,
                AdminApiConnectionClosedException,
                AdminApiTerminatedException,
                AdminApiProcedureFailureException,
                ConnectionError,
                ConnectTimeout,
                ReadTimeout):
            return None

    def _create_current_statuses(self, expected_statuses, read_statuses):
        return [self._create_current_status(expected_status, read_statuses)
                for expected_status in expected_statuses]

    @staticmethod
    def _create_current_status(expected_status, read_statuses):
        return StatusFactory.create_existing_status(component=expected_status.component,
                                                    name=expected_status.name,
                                                    admin_response=read_statuses)

    def _check_for_detected_statuses(self):
        for current_status in self._current_statuses:
            if self._is_current_status_unexpected(current_status):
                detected_status = StatusFactory.create_detected_status(component=current_status.component,
                                                                       name=current_status.name,
                                                                       value=current_status.value)
                if detected_status not in self._detected_statuses:
                    self._detected_statuses.append(detected_status)
                    self._history_of_statuses.append(detected_status)

    def _is_current_status_unexpected(self, current_status):
        for expected_status in self._expected_statuses:
            if current_status.has_only_different_value_from(expected_status):
                return True
        else:
            return False

    def _check_for_lost_statuses(self):
        lost_statuses = []

        for detected_status in self._detected_statuses:
            if self._is_detected_status_lost(detected_status):
                lost_status = StatusFactory.create_lost_status(component=detected_status.component,
                                                               name=detected_status.name,
                                                               value=detected_status.value)
                lost_statuses.append(lost_status)
                self._history_of_statuses.append(lost_status)

        for lost_status in lost_statuses:
            self._detected_statuses.remove(lost_status)

    def _is_detected_status_lost(self, detected_status):
        for current_status in self._current_statuses:
            if detected_status.has_only_different_value_from(current_status):
                return True
        else:
            return False

    @staticmethod
    def _get_time_delta(start_time, end_time):
        time_delta = end_time - start_time
        return time_delta.total_seconds()

    def _wait(self, elapsed_time=0.0):
        time_delta = self._interval - elapsed_time
        sleep(time_delta if time_delta >= 0 else 0)

    def _check_for_not_started_watch(self, action):
        if not self._keep_watching:
            raise WatchdogNotStarted(
                "Before using {} watchdog must be started first - use watch_statuses".format(action))

    def _check_if_component_exists_on_bts(self, component):
        self._log_debug_msg("Checking if component {} exists on BTS".format(component))

        try:
            self._bts.get_statuses(dist_name=component, timeout=self._interval * 6)
        except (AdminApiNoResponseException,
                AdminApiProcedureTimeoutException,
                AdminApiConnectionClosedException,
                AdminApiTerminatedException,
                AdminApiProcedureFailureException,
                ConnectionError,
                ConnectTimeout,
                ReadTimeout) as error:
            raise ComponentCheckError("BTS was unavailable during component check or "
                                      "{} component doesn't exist on BTS. Details: {} {}".format(component,
                                                                                                 type(error),
                                                                                                 error))

        self._log_debug_msg("Component {} exists on BTS".format(component))

    def _try_update_expected_status(self, expected_status):
        for current_expected_status in self._expected_statuses:
            if current_expected_status.component == expected_status.component and \
                    current_expected_status.name == expected_status.name:
                if current_expected_status.value == expected_status.value:
                    continue
                self._expected_statuses.remove(current_expected_status)
                self._expected_statuses.append(expected_status)
                break

    def _try_add_new_expected_status(self, expected_status):
        if expected_status not in self._expected_statuses:
            self._expected_statuses.append(expected_status)

    def _add_new_stop_condition(self, condition_status, watched_statuses):
        for watched_status in watched_statuses:
            if watched_status not in self._stop_conditions[watched_status]:
                self._stop_conditions[watched_status].append(condition_status)

    def _stop_watcher(self):
        self._log_debug_msg("Stopping watcher")
        self._keep_watching = False
        self._watcher.join()
        self._watcher = None
        self._log_debug_msg("Watcher stopped")

    def _disconnect_from_bts(self):
        self._bts.disconnect()

    def _reset(self):
        self._log_debug_msg("Resetting watchdog")
        self._expected_statuses = []
        self._current_statuses = []
        self._detected_statuses = []
        self._history_of_statuses = []
        self._stop_conditions = defaultdict(list)
        self._log_debug_msg("Watchdog reset")

    def _log_info_msg(self, msg):
        self._logger.info(self._format_log_msg(msg))

    def _log_debug_msg(self, msg):
        self._logger.debug(self._format_log_msg(msg))

    def _format_log_msg(self, msg):
        return msg + ' @{}'.format(id(self))
